Templates library page. URL: /app/templates

**Loader:** Get shop's custom templates + built-in global templates:
```typescript
export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);

  const [customTemplates, globalTemplates] = await Promise.all([
    db.quizTemplate.findMany({
      where: { shop: session.shop, isGlobal: false },
      orderBy: { createdAt: "desc" },
    }),
    db.quizTemplate.findMany({
      where: { isGlobal: true },
      orderBy: { usageCount: "desc" },
    }),
  ]);

  return json({ customTemplates, globalTemplates });
}
```

**Action:** Handle `use-template` intent:
```typescript
// Creates a new quiz from template data
const templateId = formData.get("templateId") as string;
const template = await db.quizTemplate.findFirst({ where: { id: templateId } });
if (!template) return json({ error: "Template not found" }, { status: 404 });

// Increment usage count
await db.quizTemplate.update({ where: { id: templateId }, data: { usageCount: { increment: 1 } } });

// Create new quiz from template
const slug = await generateUniqueSlug(session.shop, template.name);
const quiz = await db.quiz.create({
  data: {
    shop: session.shop,
    title: template.name,
    slug,
    type: "product-recommendation",
    status: "draft",
  },
});
return redirect(`/app/quizzes/${quiz.id}`);
```

