## File 2: app/routes/app.quizzes.$id.analytics.tsx

Per-quiz analytics page. URL: /app/quizzes/:id/analytics

**Loader:**
```typescript
export async function loader({ request, params }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const { id } = params;

  const days = parseInt(new URL(request.url).searchParams.get("days") ?? "30");

  // Verify quiz ownership
  const quiz = await db.quiz.findFirst({
    where: { id, shop: session.shop },
    select: { id: true, title: true, slug: true, completions: true, startCount: true, status: true },
  });
  if (!quiz) throw json({ error: "Quiz not found" }, { status: 404 });

  const startDate = new Date();
  startDate.setDate(startDate.getDate() - days);

  // Analytics data
  const [
    totalResponses,
    completedResponses,
    dailyStats,
    topResultPages,
    recentResponses,
  ] = await Promise.all([
    db.quizResponse.count({ where: { quizId: id, shop: session.shop, createdAt: { gte: startDate } } }),
    db.quizResponse.count({ where: { quizId: id, shop: session.shop, completedAt: { not: null }, createdAt: { gte: startDate } } }),
    // Daily breakdown
    db.analyticsEvent.groupBy({
      by: ["createdAt"],
      where: { quizId: id, shop: session.shop, eventType: "quiz_started", createdAt: { gte: startDate } },
      _count: { id: true },
    }).catch(() => [] as never[]),
    // Top result pages from responses
    db.quizResponse.findMany({
      where: { quizId: id, shop: session.shop, completedAt: { not: null } },
      select: { recommendedProducts: true, score: true },
      take: 100,
      orderBy: { createdAt: "desc" },
    }),
    // Recent responses
    db.quizResponse.findMany({
      where: { quizId: id, shop: session.shop },
      orderBy: { createdAt: "desc" },
      take: 10,
      select: { id: true, email: true, score: true, completedAt: true, createdAt: true, source: true, deviceType: true },
    }),
  ]);

  const completionRate = totalResponses > 0 ? Math.round((completedResponses / totalResponses) * 100) : 0;

  return json({
    quiz,
    days,
    stats: {
      totalResponses,
      completedResponses,
      completionRate,
      avgScore: 0, // Can be computed later
    },
    recentResponses,
  });
}
```

**UI:** Full analytics page with:
- Page with back action (`/app/quizzes/${id}`) and title "{quiz.title} — Analytics"
- Top stat cards (InlineGrid 4 columns):
  - Total Responses, Completed, Completion Rate, Avg Score
- Recent Responses table (IndexTable):
  - Columns: Date, Email (or "Anonymous"), Score, Status (completed/in-progress), Source, Device
  - For email: show email or "Anonymous" if null
  - For status: Badge tone "success" if completedAt, else "warning"
  - If no responses: EmptyState "No responses yet"
- Banner at top: "Install the QuizSnap widget on your storefront to start collecting responses"
  - Only show if quiz.startCount === 0 and totalResponses === 0

Add date range selector (Select component, options: 7/14/30/90 days) that uses useNavigate to change `?days=X`.
