### app/components/shared/ConfirmModal.tsx

```tsx
import { Modal, Text } from "@shopify/polaris";

interface ConfirmModalProps {
  open: boolean;
  onClose: () => void;
  onConfirm: () => void;
  title: string;
  message: string;
  confirmLabel?: string;
  destructive?: boolean;
}

export function ConfirmModal({ open, onClose, onConfirm, title, message, confirmLabel = "Delete", destructive = true }: ConfirmModalProps) {
  return (
    <Modal
      open={open}
      onClose={onClose}
      title={title}
      primaryAction={{
        content: confirmLabel,
        onAction: onConfirm,
        destructive,
      }}
      secondaryActions={[{ content: "Cancel", onAction: onClose }]}
    >
      <Modal.Section>
        <Text as="p">{message}</Text>
      </Modal.Section>
    </Modal>
  );
}
```

### app/components/shared/PlanGate.tsx

```tsx
import { Card, BlockStack, Text, Button, Badge } from "@shopify/polaris";
import type { PlanId } from "~/utils/constants";

interface PlanGateProps {
  requiredPlan: PlanId;
  currentPlan: PlanId;
  featureName: string;
  children: React.ReactNode;
}

const PLAN_ORDER: PlanId[] = ["free", "starter", "pro", "enterprise"];

export function PlanGate({ requiredPlan, currentPlan, featureName, children }: PlanGateProps) {
  const hasAccess = PLAN_ORDER.indexOf(currentPlan) >= PLAN_ORDER.indexOf(requiredPlan);

  if (hasAccess) return <>{children}</>;

  const planName = requiredPlan.charAt(0).toUpperCase() + requiredPlan.slice(1);

  return (
    <Card>
      <BlockStack gap="400">
        <BlockStack gap="200">
          <Badge tone="warning">{planName} plan required</Badge>
          <Text variant="headingMd" as="h3">{featureName}</Text>
          <Text as="p" tone="subdued">
            Upgrade to the {planName} plan to access {featureName.toLowerCase()}.
          </Text>
        </BlockStack>
        <Button url="/app/billing" variant="primary">
          Upgrade to {planName}
        </Button>
      </BlockStack>
    </Card>
  );
}
```

