import { Modal, Text } from "@shopify/polaris";

interface ConfirmModalProps {
  open: boolean;
  onClose: () => void;
  onConfirm: () => void;
  title: string;
  message: string;
  confirmLabel?: string;
  destructive?: boolean;
}

export function ConfirmModal({
  open,
  onClose,
  onConfirm,
  title,
  message,
  confirmLabel = "Delete",
  destructive = true,
}: ConfirmModalProps) {
  return (
    <Modal
      open={open}
      onClose={onClose}
      title={title}
      primaryAction={{
        content: confirmLabel,
        onAction: onConfirm,
        destructive,
      }}
      secondaryActions={[{ content: "Cancel", onAction: onClose }]}
    >
      <Modal.Section>
        <Text as="p">{message}</Text>
      </Modal.Section>
    </Modal>
  );
}

import { Card, BlockStack, Text, Button, Badge } from "@shopify/polaris";
import type { PlanId } from "~/utils/constants";

interface PlanGateProps {
  requiredPlan: PlanId;
  currentPlan: PlanId;
  featureName: string;
  children: React.ReactNode;
}

const PLAN_ORDER: PlanId[] = ["free", "starter", "pro", "enterprise"];

export function PlanGate({
  requiredPlan,
  currentPlan,
  featureName,
  children,
}: PlanGateProps) {
  const hasAccess =
    PLAN_ORDER.indexOf(currentPlan) >= PLAN_ORDER.indexOf(requiredPlan);

  if (hasAccess) return <>{children}</>;

  const planName =
    requiredPlan.charAt(0).toUpperCase() + requiredPlan.slice(1);

  return (
    <Card>
      <BlockStack gap="400">
        <BlockStack gap="200">
          <Badge tone="warning">{planName} plan required</Badge>
          <Text variant="headingMd" as="h3">
            {featureName}
          </Text>
          <Text as="p" tone="subdued">
            Upgrade to the {planName} plan to access{" "}
            {featureName.toLowerCase()}.
          </Text>
        </BlockStack>
        <Button url="/app/billing" variant="primary">
          Upgrade to {planName}
        </Button>
      </BlockStack>
    </Card>
  );
}

import { useEffect } from "react";
import { json, redirect } from "react-router";
import type {
  ActionFunctionArgs,
  HeadersFunction,
  LoaderFunctionArgs,
} from "react-router";
import { useLoaderData, useNavigation, Form, useNavigate } from "react-router";
import {
  Page,
  Layout,
  Card,
  Text,
  BlockStack,
  InlineStack,
  Badge,
  Button,
  EmptyState,
  InlineGrid,
  SkeletonPage,
  SkeletonBodyText,
  SkeletonDisplayText,
} from "@shopify/polaris";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import db from "~/db.server";

// ─── Types ────────────────────────────────────────────────────────────────────

interface TemplateMeta {
  emoji: string;
}

function parseTemplateMeta(templateData: string): TemplateMeta {
  try {
    const parsed = JSON.parse(templateData) as Record<string, unknown>;
    return {
      emoji: typeof parsed.emoji === "string" ? parsed.emoji : "📋",
    };
  } catch {
    return { emoji: "📋" };
  }
}

// ─── Hardcoded global templates shown when DB has no global templates ─────────

const HARDCODED_TEMPLATES = [
  {
    name: "Skincare Routine Finder",
    category: "skincare",
    emoji: "🧴",
    description: "Help customers find their perfect skincare routine",
  },
  {
    name: "Supplement Advisor",
    category: "health",
    emoji: "💊",
    description: "Match customers to the right supplements",
  },
  {
    name: "Style Finder",
    category: "fashion",
    emoji: "👗",
    description: "Find the perfect style for every occasion",
  },
  {
    name: "Hair Care Match",
    category: "hair",
    emoji: "💇",
    description: "Personalize hair care recommendations",
  },
  {
    name: "Fitness Advisor",
    category: "fitness",
    emoji: "🏋️",
    description: "Match fitness products to goals",
  },
  {
    name: "Pet Food Finder",
    category: "pets",
    emoji: "🐾",
    description: "Find the right food for every pet",
  },
] as const;

// ─── Slug helper ──────────────────────────────────────────────────────────────

async function generateUniqueSlug(shop: string, title: string): Promise<string> {
  const base = title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
  let slug = base;
  let counter = 0;
  while (await db.quiz.findFirst({ where: { shop, slug } })) {
    counter++;
    slug = `${base}-${counter}`;
  }
  return slug;
}

// ─── Loader ───────────────────────────────────────────────────────────────────

export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);

  try {
    const [customTemplates, globalTemplates] = await Promise.all([
      db.quizTemplate.findMany({
        where: { shop: session.shop, isGlobal: false },
        orderBy: { createdAt: "desc" },
      }),
      db.quizTemplate.findMany({
        where: { isGlobal: true },
        orderBy: { usageCount: "desc" },
      }),
    ]);

    return json({ customTemplates, globalTemplates });
  } catch (error) {
    console.error("Templates loader error:", error);
    throw json({ error: "Failed to load templates" }, { status: 500 });
  }
}

// ─── Action ───────────────────────────────────────────────────────────────────

export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  if (intent === "use-template") {
    const templateId = formData.get("templateId") as string;

    try {
      const template = await db.quizTemplate.findFirst({
        where: { id: templateId },
      });
      if (!template) {
        return json({ error: "Template not found" }, { status: 404 });
      }

      await db.quizTemplate.update({
        where: { id: templateId },
        data: { usageCount: { increment: 1 } },
      });

      const slug = await generateUniqueSlug(session.shop, template.name);
      const quiz = await db.quiz.create({
        data: {
          shop: session.shop,
          title: template.name,
          slug,
          type: "product-recommendation",
          status: "draft",
        },
      });

      return redirect(`/app/quizzes/${quiz.id}`);
    } catch (error) {
      console.error("use-template action error:", error);
      return json({ error: "Failed to create quiz from template" }, { status: 500 });
    }
  }

  return json({ error: "Unknown intent" }, { status: 400 });
}

// ─── Component ────────────────────────────────────────────────────────────────

export default function TemplatesPage() {
  const { customTemplates, globalTemplates } =
    useLoaderData<typeof loader>();
  const navigation = useNavigation();
  const shopify = useAppBridge();
  const navigate = useNavigate();

  const isSubmitting = navigation.state === "submitting";
  const submittingTemplateId = navigation.formData?.get("templateId") as
    | string
    | null;

  // Navigate to /app/quizzes/new after effect only applies to hardcoded path
  // (redirect from action handles the DB template case automatically)

  useEffect(() => {
    // No toast needed here — success redirects immediately to the quiz builder
  }, [shopify]);

  const useHardcoded = globalTemplates.length === 0;

  return (
    <Page
      title="Template Library"
      subtitle="Start faster with pre-built quizzes"
    >
      <BlockStack gap="800">
        {/* ── QuizSnap Templates ─────────────────────────────────────────── */}
        <Layout>
          <Layout.Section>
            <BlockStack gap="400">
              <Text as="h2" variant="headingLg">
                QuizSnap Templates
              </Text>
              <Text as="p" tone="subdued">
                Ready-made quizzes for popular product categories. Use one to
                get started in seconds.
              </Text>

              {useHardcoded ? (
                <InlineGrid columns={{ xs: 1, sm: 2, md: 3 }} gap="400">
                  {HARDCODED_TEMPLATES.map((t) => (
                    <div
                      key={t.name}
                      style={{
                        border: "1px solid var(--p-color-border)",
                        borderRadius: "var(--p-border-radius-300)",
                        padding: "16px",
                        background: "var(--p-color-bg-surface)",
                      }}
                    >
                      <BlockStack gap="300">
                        <Text as="p" variant="headingXl">
                          {t.emoji}
                        </Text>
                        <BlockStack gap="100">
                          <Text as="h3" variant="headingMd" fontWeight="bold">
                            {t.name}
                          </Text>
                          <Badge>{t.category}</Badge>
                        </BlockStack>
                        <Text as="p" tone="subdued">
                          {t.description}
                        </Text>
                        <Button
                          variant="primary"
                          onClick={() => navigate("/app/quizzes/new")}
                          loading={false}
                          fullWidth
                        >
                          Use template
                        </Button>
                      </BlockStack>
                    </div>
                  ))}
                </InlineGrid>
              ) : (
                <InlineGrid columns={{ xs: 1, sm: 2, md: 3 }} gap="400">
                  {globalTemplates.map((template) => {
                    const meta = parseTemplateMeta(template.templateData);
                    const isThisSubmitting =
                      isSubmitting && submittingTemplateId === template.id;
                    return (
                      <div
                        key={template.id}
                        style={{
                          border: "1px solid var(--p-color-border)",
                          borderRadius: "var(--p-border-radius-300)",
                          padding: "16px",
                          background: "var(--p-color-bg-surface)",
                        }}
                      >
                        <BlockStack gap="300">
                          <Text as="p" variant="headingXl">
                            {meta.emoji}
                          </Text>
                          <BlockStack gap="100">
                            <Text
                              as="h3"
                              variant="headingMd"
                              fontWeight="bold"
                            >
                              {template.name}
                            </Text>
                            <Badge>{template.category}</Badge>
                          </BlockStack>
                          {template.description ? (
                            <Text as="p" tone="subdued">
                              {template.description}
                            </Text>
                          ) : null}
                          <Text as="p" variant="bodySm" tone="subdued">
                            Used {template.usageCount} time
                            {template.usageCount !== 1 ? "s" : ""}
                          </Text>
                          <Form method="post">
                            <input
                              type="hidden"
                              name="intent"
                              value="use-template"
                            />
                            <input
                              type="hidden"
                              name="templateId"
                              value={template.id}
                            />
                            <Button
                              submit
                              variant="primary"
                              loading={isThisSubmitting}
                              disabled={isSubmitting}
                              fullWidth
                            >
                              Use template
                            </Button>
                          </Form>
                        </BlockStack>
                      </div>
                    );
                  })}
                </InlineGrid>
              )}
            </BlockStack>
          </Layout.Section>
        </Layout>

        {/* ── My Templates ───────────────────────────────────────────────── */}
        <Layout>
          <Layout.Section>
            <BlockStack gap="400">
              <Text as="h2" variant="headingLg">
                My Templates
              </Text>

              {customTemplates.length === 0 ? (
                <Card>
                  <EmptyState
                    heading="Save your own templates"
                    image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
                  >
                    <p>
                      Build a quiz, then save it as a template to reuse it for
                      future campaigns.
                    </p>
                  </EmptyState>
                </Card>
              ) : (
                <InlineGrid columns={{ xs: 1, sm: 2, md: 3 }} gap="400">
                  {customTemplates.map((template) => {
                    const meta = parseTemplateMeta(template.templateData);
                    const isThisSubmitting =
                      isSubmitting && submittingTemplateId === template.id;
                    return (
                      <div
                        key={template.id}
                        style={{
                          border: "1px solid var(--p-color-border)",
                          borderRadius: "var(--p-border-radius-300)",
                          padding: "16px",
                          background: "var(--p-color-bg-surface)",
                        }}
                      >
                        <BlockStack gap="300">
                          <Text as="p" variant="headingXl">
                            {meta.emoji}
                          </Text>
                          <BlockStack gap="100">
                            <Text
                              as="h3"
                              variant="headingMd"
                              fontWeight="bold"
                            >
                              {template.name}
                            </Text>
                            <Badge>{template.category}</Badge>
                          </BlockStack>
                          {template.description ? (
                            <Text as="p" tone="subdued">
                              {template.description}
                            </Text>
                          ) : null}
                          <Text as="p" variant="bodySm" tone="subdued">
                            Used {template.usageCount} time
                            {template.usageCount !== 1 ? "s" : ""}
                          </Text>
                          <Form method="post">
                            <input
                              type="hidden"
                              name="intent"
                              value="use-template"
                            />
                            <input
                              type="hidden"
                              name="templateId"
                              value={template.id}
                            />
                            <Button
                              submit
                              variant="primary"
                              loading={isThisSubmitting}
                              disabled={isSubmitting}
                              fullWidth
                            >
                              Use template
                            </Button>
                          </Form>
                        </BlockStack>
                      </div>
                    );
                  })}
                </InlineGrid>
              )}
            </BlockStack>
          </Layout.Section>
        </Layout>
      </BlockStack>
    </Page>
  );
}

