  Banner,
  SkeletonPage,
  SkeletonBodyText,
  SkeletonDisplayText,
  Box,
} from "@shopify/polaris";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import db from "~/db.server";

// ─── Loader ───────────────────────────────────────────────────────────────────

export async function loader({ request, params }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const { id } = params;

  const days = parseInt(
    new URL(request.url).searchParams.get("days") ?? "30",
    10,
  );

  const quiz = await db.quiz.findFirst({
    where: { id, shop: session.shop },
    select: {
      id: true,
      title: true,
      slug: true,
      completions: true,
      startCount: true,
      status: true,
    },
  });

  if (!quiz) {
    throw json({ error: "Quiz not found" }, { status: 404 });
  }

  const startDate = new Date();
  startDate.setDate(startDate.getDate() - days);

  try {
    const [totalResponses, completedResponses, recentResponses] =
      await Promise.all([
        db.quizResponse.count({
          where: {
            quizId: id,
            shop: session.shop,
            createdAt: { gte: startDate },
          },
        }),
        db.quizResponse.count({
          where: {
            quizId: id,
            shop: session.shop,
            completedAt: { not: null },
            createdAt: { gte: startDate },
          },
        }),
        db.quizResponse.findMany({
          where: { quizId: id, shop: session.shop },
          orderBy: { createdAt: "desc" },
          take: 10,
          select: {
            id: true,
            email: true,
            score: true,
            completedAt: true,
            createdAt: true,
            source: true,
            deviceType: true,
          },
        }),
      ]);

    const completionRate =
      totalResponses > 0
        ? Math.round((completedResponses / totalResponses) * 100)
        : 0;

    const avgScore =
      completedResponses > 0
        ? await db.quizResponse
            .aggregate({
              where: {
                quizId: id,
                shop: session.shop,
                completedAt: { not: null },
                createdAt: { gte: startDate },
              },
              _avg: { score: true },
            })
            .then((r) => Math.round(r._avg.score ?? 0))
        : 0;

    return json({
      quiz,
      days,
      stats: {
        totalResponses,
        completedResponses,
        completionRate,
        avgScore,
      },
      recentResponses: recentResponses.map((r) => ({
        ...r,
        completedAt: r.completedAt?.toISOString() ?? null,
        createdAt: r.createdAt.toISOString(),
      })),
    });
  } catch (error) {
    console.error("Quiz analytics loader error:", error);
    throw json({ error: "Failed to load analytics" }, { status: 500 });
  }
}

// ─── Date range options ───────────────────────────────────────────────────────

const DATE_RANGE_OPTIONS = [
  { label: "Last 7 days", value: "7" },
  { label: "Last 14 days", value: "14" },
  { label: "Last 30 days", value: "30" },
  { label: "Last 90 days", value: "90" },
] as const;

// ─── Stat card ────────────────────────────────────────────────────────────────

interface StatCardProps {
  label: string;
  value: string | number;
  suffix?: string;
}

function StatCard({ label, value, suffix }: StatCardProps) {
  return (
    <Card>
      <BlockStack gap="100">
        <Text as="p" variant="bodySm" tone="subdued">
          {label}
        </Text>
        <InlineStack gap="100" blockAlign="end">
          <Text as="p" variant="headingXl" fontWeight="bold">
            {value}
          </Text>
          {suffix ? (
            <Text as="p" variant="bodyMd" tone="subdued">
              {suffix}
            </Text>
          ) : null}
        </InlineStack>
      </BlockStack>
    </Card>
  );
}

// ─── Component ────────────────────────────────────────────────────────────────

export default function QuizAnalyticsPage() {
  const { quiz, days, stats, recentResponses } =
    useLoaderData<typeof loader>();
  const navigate = useNavigate();
  const [selectedDays, setSelectedDays] = useState(String(days));

  const handleDaysChange = useCallback(
    (value: string) => {
      setSelectedDays(value);
      navigate(`/app/quizzes/${quiz.id}/analytics?days=${value}`);
    },
    [navigate, quiz.id],
  );

  const showInstallBanner =
    quiz.startCount === 0 && stats.totalResponses === 0;

  const resourceName = {
    singular: "response",
    plural: "responses",
  };

  const rowMarkup = recentResponses.map((response, index) => (
    <IndexTable.Row id={response.id} key={response.id} position={index}>
      <IndexTable.Cell>
        <Text as="span" variant="bodySm">
          {new Date(response.createdAt).toLocaleDateString("en-US", {
            month: "short",
            day: "numeric",
            year: "numeric",
          })}
        </Text>
      </IndexTable.Cell>
      <IndexTable.Cell>
        <Text as="span" variant="bodySm" tone={response.email ? undefined : "subdued"}>
          {response.email ?? "Anonymous"}
        </Text>
      </IndexTable.Cell>
      <IndexTable.Cell>
        <Text as="span" variant="bodySm">
          {response.score}
        </Text>
      </IndexTable.Cell>
      <IndexTable.Cell>
        {response.completedAt ? (
          <Badge tone="success">Completed</Badge>
        ) : (
          <Badge tone="warning">In progress</Badge>
        )}
      </IndexTable.Cell>
      <IndexTable.Cell>
        <Text as="span" variant="bodySm">
          {response.source}
        </Text>
      </IndexTable.Cell>
      <IndexTable.Cell>
        <Text as="span" variant="bodySm" tone={response.deviceType ? undefined : "subdued"}>
          {response.deviceType ?? "Unknown"}
        </Text>
      </IndexTable.Cell>
    </IndexTable.Row>
  ));

  return (
    <Page
      title={`${quiz.title} — Analytics`}
      backAction={{ content: "Back to quiz", url: `/app/quizzes/${quiz.id}` }}
    >
      <BlockStack gap="600">
        {showInstallBanner && (
          <Banner
            title="Install the QuizSnap widget on your storefront to start collecting responses"
            tone="info"
          >
            <p>
              Add the quiz widget to your store theme so shoppers can take your
              quiz and generate analytics data.
            </p>
          </Banner>
        )}

        {/* ── Date range selector ──────────────────────────────────────── */}
        <InlineStack align="end">
          <Box minWidth="160px">
            <Select
              label="Date range"
              labelHidden
              options={DATE_RANGE_OPTIONS as unknown as { label: string; value: string }[]}
              value={selectedDays}
              onChange={handleDaysChange}
            />
          </Box>
        </InlineStack>

        {/* ── Stat cards ───────────────────────────────────────────────── */}
        <InlineGrid columns={{ xs: 1, sm: 2, md: 4 }} gap="400">
          <StatCard
            label="Total Responses"
            value={stats.totalResponses.toLocaleString()}
          />
          <StatCard
            label="Completed"
            value={stats.completedResponses.toLocaleString()}
          />
          <StatCard
            label="Completion Rate"
            value={stats.completionRate}
            suffix="%"
          />
          <StatCard label="Avg Score" value={stats.avgScore} />
        </InlineGrid>

        {/* ── Recent responses table ───────────────────────────────────── */}
        <Layout>
          <Layout.Section>
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd">
                  Recent Responses
                </Text>

                {recentResponses.length === 0 ? (
                  <EmptyState
                    heading="No responses yet"
                    image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
                  >
                    <p>
                      Once shoppers take your quiz, their responses will appear
                      here.
                    </p>
                  </EmptyState>
                ) : (
                  <IndexTable
                    resourceName={resourceName}
                    itemCount={recentResponses.length}
                    headings={[
                      { title: "Date" },
                      { title: "Email" },
                      { title: "Score" },
                      { title: "Status" },
                      { title: "Source" },
                      { title: "Device" },
                    ]}
                    selectable={false}
                  >
                    {rowMarkup}
                  </IndexTable>
                )}
              </BlockStack>
            </Card>
          </Layout.Section>
        </Layout>
      </BlockStack>
    </Page>
  );
}

